/**
 * The open-source licences of the About screen, read from `src/lib/about/thirdparty.json` (generated by
 * `cargo xtask licenses`).
 *
 * The file is ≈ 320 KB, so it is imported lazily when the section opens (its own chunk, never in the startup bundle).
 * Each licence text is stored once and packages refer to it by index; a package's text is its
 * segments joined with a blank line, rendered as plain text. `url` is always http(s).
 */

/** One shipped dependency. */
export interface ThirdPartyPackage {
  ecosystem: 'cargo' | 'npm'
  name: string
  version: string
  /** The declared licence as a normalised SPDX expression. */
  licence: string
  /** The alternative the app uses ("MIT" for "MIT OR Apache-2.0"). */
  used: string
  url: string
  authors: string[]
  /**
   * Indices into `ThirdParty.texts`. `cargo xtask licenses` refuses to write a package without the text of each licence
   * it is used under, so the committed file never has an empty list; the About view still says so if one ever does.
   */
  texts: number[]
}

export interface ThirdParty {
  packages: ThirdPartyPackage[]
  texts: string[]
}

function isEcosystem(value: unknown): value is ThirdPartyPackage['ecosystem'] {
  return value === 'cargo' || value === 'npm'
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((v) => typeof v === 'string')
}

/** Validates the generated file's shape (a malformed entry is dropped, never rendered half-way). */
export function parseThirdParty(raw: unknown): ThirdParty {
  const root = (typeof raw === 'object' && raw !== null ? raw : {}) as { packages?: unknown; texts?: unknown }
  const texts = isStringArray(root.texts) ? root.texts : []
  const packages: ThirdPartyPackage[] = []
  for (const item of Array.isArray(root.packages) ? root.packages : []) {
    if (typeof item !== 'object' || item === null) continue
    const p = item as Record<string, unknown>
    if (
      !isEcosystem(p.ecosystem) ||
      typeof p.name !== 'string' ||
      typeof p.version !== 'string' ||
      typeof p.licence !== 'string' ||
      typeof p.used !== 'string' ||
      typeof p.url !== 'string' ||
      !isStringArray(p.authors) ||
      !Array.isArray(p.texts)
    ) {
      continue
    }
    const indices = p.texts.filter(
      (i): i is number => Number.isInteger(i) && (i as number) >= 0 && (i as number) < texts.length,
    )
    packages.push({
      ecosystem: p.ecosystem,
      name: p.name,
      version: p.version,
      licence: p.licence,
      used: p.used,
      url: p.url,
      authors: p.authors,
      texts: indices,
    })
  }
  return { packages, texts }
}

let loading: Promise<ThirdParty> | null = null

/** Loads the notices once (a failed load is retried on the next call). */
export function loadThirdParty(): Promise<ThirdParty> {
  if (loading) return loading
  const load = import('$lib/about/thirdparty.json').then((mod) => parseThirdParty(mod.default))
  loading = load
  load.catch(() => {
    if (loading === load) loading = null
  })
  return load
}

/** The full licence text of a package (its segments joined with a blank line), or '' when it ships none. */
export function licenceText(all: ThirdParty, p: ThirdPartyPackage): string {
  return p.texts
    .map((i) => all.texts[i] ?? '')
    .filter((t) => t !== '')
    .join('\n\n')
}

/** A stable key for a package (the same crate can appear in two versions). */
export function packageKey(p: ThirdPartyPackage): string {
  return `${p.ecosystem}:${p.name}@${p.version}`
}

/** Case-insensitive match on the name, the licence used, the declared licence and the authors. */
export function matchesPackage(p: ThirdPartyPackage, query: string): boolean {
  const q = query.trim().toLowerCase()
  if (q === '') return true
  return q
    .split(/\s+/u)
    .every(
      (token) =>
        p.name.toLowerCase().includes(token) ||
        p.used.toLowerCase().includes(token) ||
        p.licence.toLowerCase().includes(token) ||
        p.authors.some((a) => a.toLowerCase().includes(token)),
    )
}
